with parsed as (select id, plan, effective_from, tier_limits, tier_prices, discounts, array_min(tier_prices) as lowest_price, slice(tier_limits, 1, 2) as first_two_limits, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps from price_tiers) select *, avg(lowest_price) over (partition by plan order by lowest_price, id rows between 6 preceding and 1 preceding) as lowest_price_avg_6_prior, last_value(lowest_price) ignore nulls over (partition by plan order by effective_from, id rows between unbounded preceding and current row) as last_known_lowest_price, row_number() over (partition by plan order by lowest_price, id) as row_seq, dense_rank() over (partition by plan order by lowest_price nulls first) as lowest_price_dense_rank from parsed
